169: export interface QuickJSOptions {
170:   /**
171:    * WASM module bytes or pre-compiled module.
172:    *
173:    * The caller is responsible for loading the WASM binary using whichever
174:    * mechanism is appropriate for their environment (e.g. `fetch()`,
175:    * `node:fs/promises`, a bundler-specific import). For convenience the
176:    * package ships the binary at the `quickjs-wasi/quickjs.wasm` subpath,
177:    * which can be resolved by bundlers (e.g. Vite's `?url` loader) or read
178:    * directly from disk.
179:    */
180:   wasm: BufferSource | WebAssembly.Module;
181:   /** Custom WASI function implementations. */
182:   wasi?: WasiOptions;
183:   /**
184:    * Maximum memory the QuickJS runtime can allocate, in bytes.
185:    * When exceeded, allocations fail and surface as JS exceptions
186:    * (e.g. `InternalError: out of memory`).
187:    */
188:   memoryLimit?: number;
189:   /**
190:    * Called periodically during JS execution. Return `true` to interrupt
191:    * the current execution with an `InternalError: interrupted` exception.
192:    * Useful for implementing execution timeouts or step limits.
193:    *
194:    * The handler is called approximately once per JS bytecode instruction,
195:    * so it should be fast.
196:    */
197:   interruptHandler?: () => boolean;
198:   /**
199:    * Called when a promise is rejected without a handler, or when a handler
200:    * is attached to a previously unhandled rejection.
201:    *
202:    * @param promise - The rejected promise
203:    * @param reason - The rejection reason/value
204:    * @param isHandled - `true` if a handler was just attached (previously unhandled),
205:    *   `false` if this is a new unhandled rejection
206:    *
207:    * Both `promise` and `reason` handles are owned by the caller and will be
208:    * disposed automatically after the callback returns.
209:    */
210:   onUnhandledRejection?: (promise: JSValueHandle, reason: JSValueHandle, isHandled: boolean) => void;
211:   /**
212:    * Module loader for ES module `import` statements. When provided, the VM
213:    * can resolve and load modules.
214:    *
215:    * Both callbacks are **synchronous** — they must return their result
216:    * immediately. For async module resolution, pre-fetch all module sources
217:    * before creating the VM and return them from a `Map` in the `load` callback.
218:    */
219:   moduleLoader?: {
220:     /**
221:      * Resolve a module specifier relative to the importing module.
222:      * Called when an `import` statement is encountered.
223:      *
224:      * @param baseName - The name of the module containing the `import` statement
225:      * @param specifier - The raw specifier string (e.g. `"./foo.js"`, `"lodash"`)
226:      * @returns The normalized/canonical module name
227:      *
228:      * If omitted, specifiers are passed through to `load` unchanged.
229:      */
230:     normalize?: (baseName: string, specifier: string) => string;
231:     /**
232:      * Load the source code for a module.
233:      *
234:      * @param moduleName - The normalized module name (from `normalize`, or the raw specifier)
235:      * @returns The module source code as a string
236:      */
237:     load: (moduleName: string) => string;
238:   };
239:   /**
240:    * Bitmask of `Intrinsics.*` flags controlling which built-in JavaScript
241:    * features are available. By default all intrinsics are enabled.
242:    *
243:    * Example: Create a VM without `eval()` or `Proxy`:
244:    * ```ts
245:    * const vm = await QuickJS.create({
246:    *   intrinsics: Intrinsics.ALL & ~Intrinsics.EVAL & ~Intrinsics.PROXY,
247:    * });
248:    * ```
249:    */
250:   intrinsics?: number;
251:   /**
252:    * Native WASM extensions to load. Each extension is a WASM shared library
253:    * (.so) compiled with wasi-sdk that links against the QuickJS C API.
254:    *
255:    * Extensions are loaded in order and their init functions are called
256:    * after the QuickJS runtime is initialized. The same extensions (in the
257:    * same order) must be provided when restoring from a snapshot.
258:    */
259:   extensions?: ExtensionDescriptor[];
260:   /**
261:    * Controls the timezone offset used by `Date` within the QuickJS sandbox.
262:    *
263:    * - **`'host'`** (default): mirrors the host environment's timezone.
264:    *   `new Date().getTimezoneOffset()` inside the VM will match the host.
265:    * - **A number**: a fixed UTC offset in **minutes** (e.g. `-480` for UTC-8,
266:    *   `60` for UTC+1). Note: this follows the `getTimezoneOffset()` sign
267:    *   convention where *west* of UTC is positive.
268:    * - **A callback `(time: number) => number`**: called with seconds since
269:    *   epoch, must return the UTC offset in minutes for that instant. Useful
270:    *   for DST-aware custom timezone logic. The callback is invoked whenever
271:    *   QuickJS converts between UTC and local time (e.g. `getHours()`,
272:    *   `toString()`, `getTimezoneOffset()`), so it may be called multiple
273:    *   times per Date operation.
274:    */
275:   timezoneOffset?: 'host' | number | ((timeSecs: number) => number);
276: }
