472: export class QuickJS {
473:   private exports: QuickJSExports;
474:   private module: WebAssembly.Module;
475:   private instance: WebAssembly.Instance;
476:   private encoder = new TextEncoder();
477:   private decoder = new TextDecoder();
478:   private disposed = false;
479: 
480:   /** Registry of host callbacks, keyed by function name */
481:   private hostCallbacks = new Map<string, HostFunction>();
482:   /** Counter for internal-only callbacks (e.g. promise settle handlers) */
483:   private nextInternalId = 1;
484:   private interruptHandler: (() => boolean) | null = null;
485:   private unhandledRejectionHandler: ((promise: JSValueHandle, reason: JSValueHandle, isHandled: boolean) => void) | null = null;
486:   private moduleNormalizeHandler: ((baseName: string, specifier: string) => string) | null = null;
487:   private moduleLoadHandler: ((moduleName: string) => string) | null = null;
488:   private timezoneOffsetHandler: ((timeSecs: number) => number) | null = null;
489: 
490:   // Cached singleton handles
491:   private _global: JSValueHandle | null = null;
492:   private _versions: Record<string, string> | null = null;
493:   private _undefined: JSValueHandle | null = null;
494:   private _null: JSValueHandle | null = null;
495:   private _true: JSValueHandle | null = null;
496:   private _false: JSValueHandle | null = null;
497: 
498:   // Handles that must be freed on dispose (e.g. unresolved promise resolve/reject functions)
499:   private _ownedHandles = new Set<JSValueHandle>();
500: 
501:   /** Loaded extensions in deterministic order */
502:   private loadedExtensions: LoadedExtension[] = [];
503: 
504:   private constructor(module: WebAssembly.Module) {
505:     this.module = module;
506:     this.instance = null!;
507:     this.exports = null!;
508:   }
509: 
510:   private setInstance(instance: WebAssembly.Instance) {
511:     this.instance = instance;
512:     this.exports = instance.exports as unknown as QuickJSExports;
513:   }
514: 
515:   // ---- Cached property accessors ----
516: 
517:   /**
518:    * Version information for the runtime and loaded native libraries.
519:    * Always includes `"quickjs-wasi"` (the npm package version) and
520:    * `"quickjs"` (the QuickJS engine version). Extensions may contribute
521:    * additional entries for their native dependencies (e.g. `"ada"`, `"mbedtls"`).
522:    */
523:   get versions(): Record<string, string> {
524:     this.assertNotDisposed();
525:     if (!this._versions) {
526:       const result: Record<string, string> = {
527:         'quickjs-wasi': VERSION,
528:         quickjs: this.readCString(this.exports.qjs_get_quickjs_version()),
529:       };
530:       for (const ext of this.loadedExtensions) {
531:         if (ext.versions) {
532:           Object.assign(result, ext.versions);
533:         }
534:       }
535:       this._versions = result;
536:     }
537:     return this._versions;
538:   }
539: 
540:   /** The global object. Cached — do not dispose. */
541:   get global(): JSValueHandle {
542:     if (!this._global) {
543:       this._global = new JSValueHandle(this, this.exports.qjs_get_global(), true);
544:     }
545:     return this._global;
546:   }
547: 
548:   /** The undefined value. Cached — do not dispose. */
549:   get undefined(): JSValueHandle {
550:     if (!this._undefined) {
551:       this._undefined = new JSValueHandle(this, this.exports.qjs_get_undefined(), true);
552:     }
553:     return this._undefined;
554:   }
555: 
556:   /** The null value. Cached — do not dispose. */
557:   get null(): JSValueHandle {
558:     if (!this._null) {
559:       this._null = new JSValueHandle(this, this.exports.qjs_get_null(), true);
560:     }
561:     return this._null;
562:   }
563: 
564:   /** The true value. Cached — do not dispose. */
565:   get true(): JSValueHandle {
566:     if (!this._true) {
567:       this._true = new JSValueHandle(this, this.exports.qjs_get_true(), true);
568:     }
569:     return this._true;
570:   }
571: 
572:   /** The false value. Cached — do not dispose. */
573:   get false(): JSValueHandle {
574:     if (!this._false) {
575:       this._false = new JSValueHandle(this, this.exports.qjs_get_false(), true);
576:     }
577:     return this._false;
578:   }
579: 
580:   /**
581:    * Create a fresh QuickJS VM instance.
582:    *
583:    * @param options - Optional configuration. Can also pass raw WASM bytes
584:    *                  directly for backwards compatibility.
585:    */
586:   static async create(options?: QuickJSOptions | BufferSource | WebAssembly.Module): Promise<QuickJS> {
587:     const opts = QuickJS.normalizeOptions(options);
588:     const module = await QuickJS.resolveModule(opts.wasm);
589:     const vm = new QuickJS(module);
590:     const { instance, wasiBuiltins, wasiUserOverrides, memoryProxy } = await QuickJS.instantiate(module, vm, opts.wasi);
591:     vm.setInstance(instance);
592: 
593:     // Initialize the WASI reactor
594:     vm.exports._initialize();
595: 
596:     // Initialize QuickJS runtime and context
597:     const result = opts.intrinsics !== undefined
598:       ? vm.exports.qjs_init2(opts.intrinsics)
599:       : vm.exports.qjs_init();
600:     if (result !== 0) {
601:       throw new Error('Failed to initialize QuickJS runtime');
602:     }
603: 
604:     // Load and initialize extensions
605:     if (opts.extensions) {
606:       const mainExports = instance.exports as Record<string, WebAssembly.ExportValue>;
607:       for (const desc of opts.extensions) {
608:         const ext = await loadExtension(desc, mainExports, wasiBuiltins, wasiUserOverrides, memoryProxy);
609:         vm.loadedExtensions.push(ext);
610:         initExtension(ext, mainExports);
611:       }
612:     }
613: 
614:     // Apply runtime limits
615:     QuickJS.applyLimits(vm, opts);
616: 
617:     return vm;
618:   }
