620:   /**
621:    * Restore a QuickJS VM from a snapshot.
622:    *
623:    * @param snapshot - The snapshot to restore from.
624:    * @param options - Optional configuration. Can also pass raw WASM bytes
625:    *                  directly for backwards compatibility.
626:    */
627:   static async restore(snapshot: Snapshot, options?: QuickJSOptions | BufferSource | WebAssembly.Module): Promise<QuickJS> {
628:     const opts = QuickJS.normalizeOptions(options);
629:     const module = await QuickJS.resolveModule(opts.wasm);
630:     const vm = new QuickJS(module);
631:     const { instance, wasiBuiltins, wasiUserOverrides, memoryProxy } = await QuickJS.instantiate(module, vm, opts.wasi);
632:     vm.setInstance(instance);
633: 
634:     const mainExports = instance.exports as Record<string, WebAssembly.ExportValue>;
635:     const exportedMemory = vm.exports.memory;
636: 
637:     // Grow memory FIRST — extensions need the memory to be large enough
638:     // for their __memory_base offsets (which were allocated in the original
639:     // larger memory during create()).
640:     const currentPages = exportedMemory.buffer.byteLength / 65536;
641:     const neededPages = Math.ceil(snapshot.memory.byteLength / 65536);
642:     if (neededPages > currentPages) {
643:       exportedMemory.grow(neededPages - currentPages);
644:     }
645: 
646:     // Re-instantiate extensions BEFORE overwriting memory.
647:     // This populates the indirect function table with the extension's
648:     // function pointers (via elem segments and __wasm_apply_data_relocs).
649:     // We use the exact same memory/table bases from the snapshot so that
650:     // function table indices match what the snapshotted QuickJS state expects.
651:     if (snapshot.extensions.length > 0) {
652:       const descriptors = opts.extensions ?? [];
653:       vm.loadedExtensions = await restoreExtensions(
654:         descriptors,
655:         snapshot.extensions,
656:         mainExports,
657:         wasiBuiltins,
658:         wasiUserOverrides,
659:         memoryProxy,
660:       );
661:     }
662: 
663:     // Copy snapshot data into the module's own memory.
664:     // This overwrites EVERYTHING — including the regions that extensions
665:     // just initialized. That's correct because the snapshot already contains
666:     // the complete state including extension data.
667:     const dst = new Uint8Array(exportedMemory.buffer);
668:     dst.set(snapshot.memory);
669: 
670:     // Set runtime/context pointers (they already exist in the restored memory)
671:     vm.exports.qjs_set_runtime_and_context(snapshot.runtimePtr, snapshot.contextPtr);
672: 
673:     // Restore the stack pointer
674:     vm.exports.__stack_pointer.value = snapshot.stackPointer;
675: 
676:     // Apply runtime limits
677:     QuickJS.applyLimits(vm, opts);
678: 
679:     return vm;
680:   }
