894:   private static async instantiate(module: WebAssembly.Module, vm: QuickJS, wasiOptions?: WasiOptions): Promise<{
895:     instance: WebAssembly.Instance;
896:     wasiBuiltins: WasiImports;
897:     wasiUserOverrides: WasiImports | undefined;
898:     memoryProxy: WebAssembly.Memory;
899:   }> {
900:     let memory: WebAssembly.Memory | null = null;
901: 
902:     // Create a memory proxy that defers to the actual memory once set.
903:     // This allows WASI override factories to close over the memory reference
904:     // before the WASM instance is created.
905:     const memoryProxy = new Proxy({} as WebAssembly.Memory, {
906:       get(_target, prop) {
907:         return (memory as any)[prop];
908:       },
909:     });
910: 
911:     // Build the builtins (no user overrides)
912:     const wasiBuiltins = createWasiShim(() => memory!);
913: 
914:     // Resolve user overrides via factory
915:     const wasiUserOverrides = wasiOptions ? wasiOptions(memoryProxy) : undefined;
916: 
917:     // Final shim for the main module: builtins + user overrides
918:     const wasiShim = { ...wasiBuiltins, ...wasiUserOverrides };
919: 
920:     const hostCall = (namePtr: number, nameLen: number, thisPtr: number, argc: number, argvPtr: number): number => {
921:       return vm.handleHostCall(namePtr, nameLen, thisPtr, argc, argvPtr);
922:     };
923: 
924:     const hostInterrupt = (): number => {
925:       return vm.interruptHandler ? (vm.interruptHandler() ? 1 : 0) : 0;
926:     };
927: 
928:     const hostPromiseRejection = (promisePtr: number, reasonPtr: number, isHandled: number): void => {
929:       if (!vm.unhandledRejectionHandler) {
930:         // No handler registered — free the heap-allocated values
931:         vm.exports.qjs_free_value(promisePtr);
932:         vm.exports.qjs_free_value(reasonPtr);
933:         return;
934:       }
935:       const promise = new JSValueHandle(vm, promisePtr);
936:       const reason = new JSValueHandle(vm, reasonPtr);
937:       try {
938:         vm.unhandledRejectionHandler(promise, reason, isHandled !== 0);
939:       } finally {
940:         promise.dispose();
941:         reason.dispose();
942:       }
943:     };
944: 
945:     // Module normalizer: resolve a specifier relative to a base name.
946:     // Returns a malloc'd null-terminated string in WASM memory, or 0 (NULL) on error.
947:     const hostModuleNormalize = (baseNamePtr: number, namePtr: number): number => {
948:       if (!vm.moduleNormalizeHandler) {
949:         // No normalize handler — return a copy of the specifier as-is
950:         const name = vm.readCString(namePtr);
951:         return vm.writeString(name).ptr;
952:       }
953:       const baseName = vm.readCString(baseNamePtr);
954:       const specifier = vm.readCString(namePtr);
955:       try {
956:         const normalized = vm.moduleNormalizeHandler(baseName, specifier);
957:         return vm.writeString(normalized).ptr;
958:       } catch {
959:         return 0;
960:       }
961:     };
962: 
963:     // Module loader: return source code for a module.
964:     // Returns a malloc'd string pointer, writes length to *outLenPtr.
965:     const hostModuleLoad = (namePtr: number, outLenPtr: number): number => {
966:       if (!vm.moduleLoadHandler) return 0;
967:       const name = vm.readCString(namePtr);
968:       try {
969:         const source = vm.moduleLoadHandler(name);
970:         const { ptr, len } = vm.writeString(source);
971:         new Uint32Array(vm.exports.memory.buffer, outLenPtr, 1)[0] = len;
972:         return ptr;
973:       } catch {
974:         return 0;
975:       }
976:     };
977: 
978:     // host_get_timezone_offset receives time as split i32 (hi, lo) and
979:     // returns the UTC offset in seconds.
980:     const hostGetTimezoneOffset = (hi: number, lo: number): number => {
981:       const timeSecs = Number((BigInt(hi) << 32n) | BigInt(lo >>> 0));
982:       return vm.timezoneOffsetHandler ? vm.timezoneOffsetHandler(timeSecs) : 0;
983:     };
984: 
985:     const instance = await WebAssembly.instantiate(module, {
986:       env: {
987:         host_call: hostCall,
988:         host_interrupt: hostInterrupt,
989:         host_promise_rejection: hostPromiseRejection,
990:         host_module_normalize: hostModuleNormalize,
991:         host_module_load: hostModuleLoad,
992:         host_get_timezone_offset: hostGetTimezoneOffset,
993:       },
994:       wasi_snapshot_preview1: wasiShim,
995:     });
996: 
997:     memory = (instance.exports as any).memory as WebAssembly.Memory;
998:     return { instance, wasiBuiltins, wasiUserOverrides, memoryProxy };
999:   }
