1001:   /**
1002:    * Called from WASM when a host function is invoked from QuickJS code.
1003:    */
1004:   private handleHostCall(namePtr: number, nameLen: number, thisPtr: number, argc: number, argvPtr: number): number {
1005:     const name = this.decoder.decode(new Uint8Array(this.exports.memory.buffer, namePtr, nameLen));
1006:     const callback = this.hostCallbacks.get(name);
1007:     if (!callback) {
1008:       return this.exports.qjs_get_undefined();
1009:     }
1010: 
1011:     const thisHandle = new JSValueHandle(this, thisPtr);
1012: 
1013:     const args: JSValueHandle[] = [];
1014:     if (argc > 0 && argvPtr !== 0) {
1015:       const view = new DataView(this.exports.memory.buffer);
1016:       for (let i = 0; i < argc; i++) {
1017:         const argPtr = view.getUint32(argvPtr + i * 4, true);
1018:         args.push(new JSValueHandle(this, argPtr));
1019:       }
1020:     }
1021: 
1022:     try {
1023:       const result = callback.call(thisHandle, ...args);
1024:       return this.exports.qjs_dup_value(result.ptr);
1025:     } catch (err) {
1026:       // Throw an exception inside QuickJS and return NULL to signal
1027:       // to the C trampoline that an exception was thrown.
1028:       const errHandle = this.newError(err instanceof Error ? err : String(err));
1029:       this.exports.qjs_throw(errHandle.ptr);
1030:       errHandle.dispose();
1031:       return 0;
1032:     }
1033:   }
