1056:   // ---- Public API ----
1057: 
1058:   /**
1059:    * Check if a result handle is an exception and throw a JSException if so.
1060:    * Used internally by evalCode and callFunction.
1061:    */
1062:   private throwIfException(result: JSValueHandle): JSValueHandle {
1063:     if (this.exports.qjs_is_exception(result.ptr) !== 0) {
1064:       const exc = this.getException();
1065:       result.dispose();
1066:       // Track the handle so it gets cleaned up if the VM is disposed
1067:       // before the caller disposes the exception.
1068:       this._ownedHandles.add(exc);
1069:       throw new JSException(exc);
1070:     }
1071:     return result;
1072:   }
