1074:   /**
1075:    * Evaluate JavaScript code and return the result as a handle.
1076:    * If the code throws, a `JSException` (which extends `Error`) is thrown
1077:    * on the host side — matching standard JavaScript semantics.
1078:    *
1079:    * @param code - The JavaScript source code to evaluate.
1080:    * @param filename - Optional filename for error stack traces (default `'<eval>'`).
1081:    * @param flags - Optional bitwise OR of `EvalFlags.*` constants.
1082:    *   For example, pass `EvalFlags.ASYNC` to allow top-level `await` — the
1083:    *   returned handle will be a Promise that resolves to the completion value.
1084:    */
1085:   evalCode(code: string, filename: string = '<eval>', flags: number = 0): JSValueHandle {
1086:     this.assertNotDisposed();
1087:     const codeStr = this.writeString(code);
1088:     const fnStr = this.writeString(filename);
1089:     const resultPtr = this.exports.qjs_eval(codeStr.ptr, codeStr.len, fnStr.ptr, flags);
1090:     this.exports.wasm_free(codeStr.ptr);
1091:     this.exports.wasm_free(fnStr.ptr);
1092:     return this.throwIfException(new JSValueHandle(this, resultPtr));
1093:   }
