1095:   /**
1096:    * Compile JavaScript source code to bytecode without executing it.
1097:    * The returned `Uint8Array` can be stored, transferred, or later executed
1098:    * with `evalBytecode()`.
1099:    *
1100:    * @param code - The JavaScript source code to compile.
1101:    * @param filename - Optional filename for error stack traces (default `'<compile>'`).
1102:    * @param evalFlags - Optional bitwise OR of `EvalFlags.*` constants.
1103:    *   Use `EvalFlags.TYPE_MODULE` to compile as a module.
1104:    * @param compileFlags - Optional bitwise OR of `CompileFlags.*` constants.
1105:    *   Use `CompileFlags.STRIP_SOURCE` and/or `CompileFlags.STRIP_DEBUG` to
1106:    *   reduce bytecode size.
1107:    */
1108:   compile(code: string, filename: string = '<compile>', evalFlags: number = 0, compileFlags: number = 0): Uint8Array {
1109:     this.assertNotDisposed();
1110:     const codeStr = this.writeString(code);
1111:     const fnStr = this.writeString(filename);
1112:     // Allocate space for the output length (size_t = 4 bytes in wasm32)
1113:     const outLenPtr = this.exports.wasm_malloc(4);
1114:     const bufPtr = this.exports.qjs_compile(codeStr.ptr, codeStr.len, fnStr.ptr, evalFlags, compileFlags, outLenPtr);
1115:     this.exports.wasm_free(codeStr.ptr);
1116:     this.exports.wasm_free(fnStr.ptr);
1117:     if (bufPtr === 0) {
1118:       this.exports.wasm_free(outLenPtr);
1119:       // Compilation failed — throw the QuickJS exception
1120:       const exc = this.getException();
1121:       throw new Error(`Compilation error: ${exc.toString()}`);
1122:     }
1123:     const outLen = new Uint32Array(this.exports.memory.buffer, outLenPtr, 1)[0];
1124:     this.exports.wasm_free(outLenPtr);
