401: /*
402:  * Compute memory usage statistics and write them into a caller-provided
403:  * buffer as an array of int64_t values. The buffer must hold at least
404:  * QJS_MEMORY_USAGE_FIELD_COUNT int64_t values (currently 24 fields).
405:  *
406:  * Fields (in order):
407:  *   0: malloc_size       1: malloc_limit      2: memory_used_size
408:  *   3: malloc_count      4: memory_used_count  5: atom_count
409:  *   6: atom_size         7: str_count          8: str_size
410:  *   9: obj_count        10: obj_size          11: prop_count
411:  *  12: prop_size        13: shape_count       14: shape_size
412:  *  15: js_func_count    16: js_func_size      17: js_func_code_size
413:  *  18: js_func_pc2line_count  19: js_func_pc2line_size
414:  *  20: c_func_count     21: array_count       22: fast_array_count
415:  *  23: fast_array_elements
416:  *  24: binary_object_count  25: binary_object_size
417:  */
418: __attribute__((export_name("qjs_compute_memory_usage")))
419: void qjs_compute_memory_usage(int64_t *out) {
420:     if (!rt) return;
421:     JSMemoryUsage s;
422:     JS_ComputeMemoryUsage(rt, &s);
423:     out[0]  = s.malloc_size;
424:     out[1]  = s.malloc_limit;
425:     out[2]  = s.memory_used_size;
426:     out[3]  = s.malloc_count;
427:     out[4]  = s.memory_used_count;
428:     out[5]  = s.atom_count;
429:     out[6]  = s.atom_size;
430:     out[7]  = s.str_count;
431:     out[8]  = s.str_size;
432:     out[9]  = s.obj_count;
433:     out[10] = s.obj_size;
434:     out[11] = s.prop_count;
435:     out[12] = s.prop_size;
436:     out[13] = s.shape_count;
437:     out[14] = s.shape_size;
438:     out[15] = s.js_func_count;
439:     out[16] = s.js_func_size;
440:     out[17] = s.js_func_code_size;
441:     out[18] = s.js_func_pc2line_count;
442:     out[19] = s.js_func_pc2line_size;
443:     out[20] = s.c_func_count;
444:     out[21] = s.array_count;
445:     out[22] = s.fast_array_count;
446:     out[23] = s.fast_array_elements;
447:     out[24] = s.binary_object_count;
448:     out[25] = s.binary_object_size;
449: }
