473: /* ---- Bytecode compilation ---- */
474: 
475: /*
476:  * Compile JS source to bytecode without executing it.
477:  * Returns a pointer to the serialized bytecode buffer, and writes the
478:  * buffer length to *out_len. The caller must free the returned pointer
479:  * with wasm_free().
480:  *
481:  * Returns NULL on compilation error (exception is set on the context).
482:  *
483:  * write_flags controls what is included in the bytecode:
484:  *   JS_WRITE_OBJ_BYTECODE (1)  - allow function/module (required)
485:  *   JS_WRITE_OBJ_STRIP_SOURCE (16) - omit source code
486:  *   JS_WRITE_OBJ_STRIP_DEBUG (32)  - omit debug info
487:  */
488: __attribute__((export_name("qjs_compile")))
489: uint8_t *qjs_compile(const char *code, size_t code_len, const char *filename,
490:                       int eval_flags, int write_flags, size_t *out_len) {
491:     JSValue obj = JS_Eval(ctx, code, code_len, filename,
492:                           eval_flags | JS_EVAL_FLAG_COMPILE_ONLY);
493:     if (JS_IsException(obj)) {
494:         *out_len = 0;
495:         return NULL;
496:     }
497:     uint8_t *buf = JS_WriteObject(ctx, out_len, obj, write_flags | JS_WRITE_OBJ_BYTECODE);
498:     JS_FreeValue(ctx, obj);
499:     return buf; /* caller frees with js_free(ctx, buf) or wasm_free() */
500: }
501: 
502: /*
503:  * Load and evaluate previously compiled bytecode.
504:  * buf/buf_len is the serialized bytecode from qjs_compile.
505:  * Returns a heap-allocated JSValue* with the evaluation result.
506:  */
507: __attribute__((export_name("qjs_eval_bytecode")))
508: JSValue *qjs_eval_bytecode(const uint8_t *buf, size_t buf_len) {
509:     JSValue obj = JS_ReadObject(ctx, buf, buf_len, JS_READ_OBJ_BYTECODE);
510:     if (JS_IsException(obj)) {
511:         return jsvalue_to_heap(obj);
512:     }
513:     /* For modules, resolve dependencies first */
514:     if (JS_VALUE_GET_TAG(obj) == JS_TAG_MODULE) {
515:         if (JS_ResolveModule(ctx, obj) < 0) {
516:             JS_FreeValue(ctx, obj);
517:             return jsvalue_to_heap(JS_EXCEPTION);
518:         }
519:     }
520:     JSValue result = JS_EvalFunction(ctx, obj);
521:     /* JS_EvalFunction consumes obj, no need to free it */
522:     return jsvalue_to_heap(result);
523: }
