577: /*
578:  * Get the description of a symbol. For global symbols (Symbol.for()),
579:  * returns the key via Symbol.keyFor(). For local symbols, returns
580:  * the description property.
581:  *
582:  * Returns:
583:  *   0 = not a symbol
584:  *   1 = global symbol (description written to out)
585:  *   2 = local symbol (description written to out)
586:  */
587: __attribute__((export_name("qjs_get_symbol_description")))
588: int qjs_get_symbol_description(JSValue *val, JSValue **desc_out) {
589:     if (!JS_IsSymbol(*val)) return 0;
590: 
591:     /* Try Symbol.keyFor(sym) to detect global symbols */
592:     JSValue global = JS_GetGlobalObject(ctx);
593:     JSValue symbol_obj = JS_GetPropertyStr(ctx, global, "Symbol");
594:     JSValue key_for_fn = JS_GetPropertyStr(ctx, symbol_obj, "keyFor");
595:     JSValue key_for_result = JS_Call(ctx, key_for_fn, symbol_obj, 1, val);
596:     JS_FreeValue(ctx, key_for_fn);
597:     JS_FreeValue(ctx, symbol_obj);
598:     JS_FreeValue(ctx, global);
599: 
600:     if (!JS_IsUndefined(key_for_result)) {
601:         /* Global symbol — keyFor returned the description string */
602:         *desc_out = jsvalue_to_heap(key_for_result);
603:         return 1;
604:     }
605:     JS_FreeValue(ctx, key_for_result);
606: 
607:     /* Local symbol — get the .description property */
608:     JSValue desc = JS_GetPropertyStr(ctx, *val, "description");
609:     *desc_out = jsvalue_to_heap(desc);
610:     return 2;
611: }
