118: /** Read a ULEB128-encoded integer from a byte array */
119: function readULEB128(bytes: Uint8Array, offset: { value: number }): number {
120:   let result = 0;
121:   let shift = 0;
122:   while (offset.value < bytes.length) {
123:     const byte = bytes[offset.value++];
124:     result |= (byte & 0x7f) << shift;
125:     if ((byte & 0x80) === 0) break;
126:     shift += 7;
127:   }
128:   return result;
