  if (sections.length === 0) return null;

  const bytes = new Uint8Array(sections[0]);
  const offset = { value: 0 };

  const info: DylinkInfo = {
    memorySize: 0,
    memoryAlignment: 0,
    tableSize: 0,
    tableAlignment: 0,
    needed: [],
